window.AUTH=window.AUTH||{};window.AUTH["06-179"]={"d":"06-179","id":"2007/06-179","n":"Riegel v. Medtronic, Inc.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondent","date":"","url":"https://www.justice.gov/osg/media/200466/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/riegel-v-medtronic-inc-amicus-merits","n":56}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep552/usrep552312/usrep552312.pdf","tr":true,"items":[{"t":"case","label":"Adickes v. S.H. Kress & Co.","cite":"398 U.S. 144","y":1970,"id":"1969/79","sc":1,"sum":"Petitioner is a white school teacher who was refused service in respondent's lunchroom when she was accompanied by six Negro students, and who was arrested for vagrancy by the Hattiesburg, Mississippi, police when she left respondent's premises. She filed a complaint in the Federal District Court to recover damages alleging deprivation of her right under the Equal Protection Clause not to be discriminated against on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"op":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"0":"24, 28"}},{"t":"case","label":"Bates v. Dow Agrosciences LLC","cite":"544 U.S. 431","y":2005,"id":"2004/03-388","sc":1,"op":5,"ar":2,"sum":"Noting that a ﬁnding that “[7 U. S. C.] § 136v(b) may pre-empt judge­ made rules, as well as statutes and regulations, says nothing about the scope of that pre-emption,” and proceeding to determine whether the par­ ticular common-law rules at issue in that case satisﬁed the conditions of pre-emption.","sumSrc":"opinion","by":{"0":"16, 17, 25, 26"}},{"t":"case","label":"Brooks v. Howmedica, Inc.","cite":"273 F.3d 785","y":2001,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/273/785/","by":{"0":"13"}},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Comm.","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"ar":1,"sum":"The Court held that the plaintiffs' state-law fraud-on-the-FDA claims conflicted with, and were therefore pre-empted by, the FDCA, as amended by the MDA. \"The conflict,\" wrote Chief Justice Rehnquist for the Court, \"stems from the fact that the federal statutory scheme amply empowers the FDA to punish and deter fraud against the Agency, and that this authority is used by the Agency to achieve a somewhat delicate balance of statutory objectives.","sumSrc":"Oyez","by":{"0":"9"}},{"t":"case","label":"Chicago & N.W. Transp. Co. v. Kalo Brick & Tile Co.","cite":"450 U.S. 311","y":1981,"id":"1980/79-1336","sc":1,"sum":"The Interstate Commerce Act precludes a shipper from pressing a state-court action for damages against a regulated rail carrier when, as here, the ICC, in approving the carrier's application for abandonment, reaches the merits of the matters the shipper seeks to raise in state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Cipollone v. Liggett Group, Inc.","cite":"505 U.S. 504","y":1992,"id":"1991/90-1038","sc":1,"op":5,"sum":"Explaining that the fact that “the pre-emptive scope of § 5(b) cannot be limited to positive enactments does not mean that that section pre-empts all common-law claims” and proceeding to analyze “each of petitioner’s common-law claims to determine whether it is in fact pre-empted”.","sumSrc":"opinion","by":{"0":"16, 17"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Geier v. American Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"op":1,"ar":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Hines v. Davidowitz","cite":"312 U.S. 52","y":1941,"id":"scdb/1940-064","sc":1,"op":1,"sum":"1. Applicable legislation enacted while the case was pending on appeal will be enforced by the appellate court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Ling v. Liquors","cite":"703 P.2d 731","y":1985,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/703/731/","by":{"0":"18"}},{"t":"case","label":"Medtronic, Inc. v. Lohr","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"op":17,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n v. State Farm Mutual Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"San Diego Bldg. Trades Council v. Garmon","cite":"359 U.S. 236","y":1959,"id":"1958/66","sc":1,"sum":"Although the National Labor Relations Board had declined to exercise jurisdiction, a California state court was precluded by the National Labor Relations Act from awarding damages to respondents under state law for economic injuries resulting from the peaceful picketing of their plant by labor unions which had not been selected by a majority of respondents' employees as their bargaining agents.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"United States v. Rutherford","cite":"442 U.S. 544","y":1979,"id":"1978/78-605","sc":1,"sum":"The Act makes no express exception for drugs used by the terminally ill and no implied exemption is necessary to attain congressional objectives or to avert an unreasonable reading of the terms \"safe\" and \"effective\" in § 201 (p) (1). Pp. 551-559. UNITED STATES v. RUTHERFORD (a) Nothing in the legislative history suggests that Congress intended protection only for persons suffering from curable diseases. Moreover, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"usc","label":"21 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/21/301","stext":{"head":"§301. Short title","paras":[[0,"This chapter may be cited as the Federal Food, Drug, and Cosmetic Act."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/301?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§301. Short title","tname":"Food and Drugs","by":{"0":"1"}},{"t":"usc","label":"21 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/21/355","subs":["(d)"],"stext":{"head":"§355. New drugs","paras":[[0,"(a) Necessity of effective approval of application"],[0,"No person shall introduce or deliver for introduction into interstate commerce any new drug, unless an approval of an application filed pursuant to subsection (b) or (j) is effective with respect to such drug."],[0,"(b) Filing application; contents"],[0,"(1)(A) Any person may file with the Secretary an application with respect to any drug subject to the provisions of subsection (a). Such persons shall submit to the Secretary as part of the application—"],[1,"(i) full reports of investigations which have been made to show whether such drug is safe for use and whether such drug is effective in use;"],[1,"(ii) a full list of the articles used as components of such drug;"],[1,"(iii) a full statement of the composition of such drug;"],[1,"(iv) a full description of the methods used in, and the facilities and controls used for, the manufacture, processing, and packing of such drug;"],[1,"(v) such samples of such drug and of the articles used as components thereof as the Secretary may require;"],[1,"(vi) specimens of the labeling proposed to be used for such drug;"],[1,"(vii) any assessments required under section 355c of this title; and"],[1,"(viii) the patent number and expiration date of each patent for which a claim of patent infringement could reasonably be asserted if a person not licensed by the owner of the patent engaged in the manufacture, use, or sale of the drug, and that—"],[2,"(I) claims the drug for which the applicant submitted the application and is a drug substance (active ingredient) patent or a drug product (formulation or composition) patent; or"],[2,"(II) claims a method of using such drug for which approval is sought or has been granted in the application."],[0,"(B) If an application is filed under this subsection for a drug, and a patent of the type described in subparagraph (A)(viii) is issued after the filing date but before approval of the application, the applicant shall amend the application to include the patent number and expiration date."],[0,"(2) An application submitted under paragraph (1) for a drug for which the investigations described in clause (A) of such paragraph and relied upon by the applicant for approval of the application were not conducted by or for the applicant and for which the applicant has not obtained a right of reference or use from the person by or for whom the investigations were conducted shall also include—"],[1,"(A) a certification, in the opinion of the applicant and to the best of his knowledge, with respect to each patent which claims the drug for which such investigations were conducted or which claims a use for such drug for which the applicant is seeking approval under this subsection and for which information is required to be filed under paragraph (1) or subsection (c)—"],[2,"(i) that such patent information has not been filed,"],[2,"(ii) that such patent has expired,"],[2,"(iii) of the date on which such patent will expire, or"],[2,"(iv) that such patent is invalid or will not be infringed by the manufacture, use, or sale of the new drug for which the application is submitted; and"],[1,"(B) if with respect to the drug for which investigations described in paragraph (1)(A) were conducted information was filed under paragraph (1) or subsection (c) for a method of use patent which does not claim a use for which the applicant is seeking approval under this subsection, a statement that the method of use patent does not claim such a use."],[0,"(3) Notice of opinion that patent is invalid or will not be infringed.—"],[1,"(A) Agreement to give notice.—An applicant that makes a certification described in paragraph (2)(A)(iv) shall include in the application a statement that the applicant will give notice as required by this paragraph."],[1,"(B) Timing of notice.—An applicant that makes a certification described in paragraph (2)(A)(iv) shall give notice as required under this paragraph—"],[2,"(i) if the certification is in the application, not later than 20 days after the date of the postmark on the notice with which the Secretary informs the applicant that the application has been filed; or"],[2,"(ii) if the certification is in an amendment or supplement to the application, at the time at which the applicant submits the amendment or supplement, regardless of whether the applicant has already given notice with respect to another such certification contained in the application or in an amendment or supplement to the application."],[1,"(C) Recipients of notice.—An applicant required under this paragraph to give notice shall give notice to—"],[2,"(i) each owner of the patent that is the subject of the certification (or a representative of the owner designated to receive such a notice); and"],[2,"(ii) the holder of the approved application under this subsection for the drug that is claimed by the patent or a use of which is claimed by the patent (or a representative of the holder designated to receive such a notice)."],[1,"(D) Contents of notice.—A notice required under this paragraph shall—"],[2,"(i) state that an application that contains data from bioavailability or bioequivalence studies has been submitted under this subsection for the drug with respect to which the certification is made to obtain approval to engage in the commercial manufacture, use, or sale of the drug before the expiration of the patent referred to in the certification; and"],[2,"(ii) include a detailed statement of the factual and legal basis of the opinion of the applicant that the patent is invalid or will not be infringed."],[0,"(4)(A) An applicant may not amend or supplement an application referred to in paragraph (2) to seek approval of a drug that is a different drug than the drug identified in the application as submitted to the Secretary."],[0,"(B) With respect to the drug for which such an application is submitted, nothing in this subsection or subsection (c)(3) prohibits an applicant from amending or supplementing the application to seek approval of a different strength."],[0,"(5)(A) The Secretary shall issue guidance for the individuals who review applications submitted under paragraph (1) or under section 262 of title 42, which shall relate to promptness in conducting the review, technical excellence, lack of bias and conflict of interest, and knowledge of regulatory and scientific standards, and which shall apply equally to all individuals who review such applications."],[0,"(B) The Secretary shall meet with a sponsor of an investigation or an applicant for approval for a drug under this subsection or section 262 of title 42 if the sponsor or applicant makes a reasonable written request for a meeting for the purpose of reaching agreement on the design and size—"],[1,"(i)(I) of clinical trials intended to form the primary basis of an effectiveness claim; or"],[1,"(II) in the case where human efficacy studies are not ethical or feasible, of animal and any associated clinical trials which, in combination, are intended to form the primary basis of an effectiveness claim; or"],[1,"(ii) with respect to an application for approval of a biological product under section 262(k) of title 42, of any necessary clinical study or studies."],[0,"The sponsor or applicant shall provide information necessary for discussion and agreement on the design and size of the clinical trials. Minutes of any such meeting shall be prepared by the Secretary and made available to the sponsor or applicant upon request."],[0,"(C) Any agreement regarding the parameters of the design and size of clinical trials of a new drug under this paragraph that is reached between the Secretary and a sponsor or applicant shall be reduced to writing and made part of the administrative record by the Secretary. Such agreement shall not be changed after the testing begins, except—"],[1,"(i) with the written agreement of the sponsor or applicant; or"],[1,"(ii) pursuant to a decision, made in accordance with subparagraph (D) by the director of the reviewing division, that a substantial scientific issue essential to determining the safety or effectiveness of the drug has been identified after the testing has begun."],[0,"(D) A decision under subparagraph (C)(ii) by the director shall be in writing and the Secretary shall provide to the sponsor or applicant an opportunity for a meeting at which the director and the sponsor or applicant will be present and at which the director will document the scientific issue involved."],[0,"(E) The written decisions of the reviewing division shall be binding upon, and may not directly or indirectly be changed by, the field or compliance division personnel unless such field or compliance division personnel demonstrate to the reviewing division why such decision should be modified."],[0,"(F) No action by the reviewing division may be delayed because of the unavailability of information from or action by field personnel unless the reviewing division determines that a delay is necessary to assure the marketing of a safe and effective drug."],[0,"(G) For purposes of this paragraph, the reviewing division is the division responsible for the review of an application for approval of a drug under this subsection or section 262 of title 42 (including all scientific and medical matters, chemistry, manufacturing, and controls)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/355?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§355. New drugs","tname":"Food and Drugs","by":{"0":"11"}},{"t":"usc","label":"7 U.S.C. § 136v","url":"https://www.law.cornell.edu/uscode/text/7/136v","subs":["(b)"],"stext":{"head":"§136v. Authority of States","paras":[[0,"(a) In general"],[0,"A State may regulate the sale or use of any federally registered pesticide or device in the State, but only if and to the extent the regulation does not permit any sale or use prohibited by this subchapter."],[0,"(b) Uniformity"],[0,"Such State shall not impose or continue in effect any requirements for labeling or packaging in addition to or different from those required under this subchapter."],[0,"(c) Additional uses"],[0,"(1) A State may provide registration for additional uses of federally registered pesticides formulated for distribution and use within that State to meet special local needs in accord with the purposes of this subchapter and if registration for such use has not previously been denied, disapproved, or canceled by the Administrator. Such registration shall be deemed registration under section 136a of this title for all purposes of this subchapter, but shall authorize distribution and use only within such State."],[0,"(2) A registration issued by a State under this subsection shall not be effective for more than ninety days if disapproved by the Administrator within that period. Prior to disapproval, the Administrator shall, except as provided in paragraph (3) of this subsection, advise the State of the Administrator's intention to disapprove and the reasons therefor, and provide the State time to respond. The Administrator shall not prohibit or disapprove a registration issued by a State under this subsection (A) on the basis of lack of essentiality of a pesticide or (B) except as provided in paragraph (3) of this subsection, if its composition and use patterns are similar to those of a federally registered pesticide."],[0,"(3) In no instance may a State issue a registration for a food or feed use unless there exists a tolerance or exemption under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] that permits the residues of the pesticides on the food or feed. If the Administrator determines that a registration issued by a State is inconsistent with the Federal Food, Drug, and Cosmetic Act, or the use of, a pesticide under a registration issued by a State constitutes an imminent hazard, the Administrator may immediately disapprove the registration."],[0,"(4) If the Administrator finds, in accordance with standards set forth in regulations issued under section 136w of this title, that a State is not capable of exercising adequate controls to assure that State registration under this section will be in accord with the purposes of this subchapter or has failed to exercise adequate controls, the Administrator may suspend the authority of the State to register pesticides until such time as the Administrator is satisfied that the State can and will exercise adequate controls. Prior to any such suspension, the Administrator shall advise the State of the Administrator's intention to suspend and the reasons therefor and provide the State time to respond."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/7/136v?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§136v. Authority of States","tname":"Agriculture","by":{"0":"25"}},{"t":"usc","label":"21 U.S.C. § 360c","url":"https://www.law.cornell.edu/uscode/text/21/360c","subs":["(a)(1)","(a)(1)(A)","(a)(1)(B)","(a)(1)(C)","(a)(2)(C)"],"stext":{"head":"§360c. Classification of devices intended for human use","paras":[[0,"(a) Classes of devices"],[0,"(1) There are established the following classes of devices intended for human use:"],[1,"(A) Class I, General Controls.—"],[2,"(i) A device for which the controls authorized by or under section 351, 352, 360, 360f, 360h, 360i, or 360j of this title or any combination of such sections are sufficient to provide reasonable assurance of the safety and effectiveness of the device."],[2,"(ii) A device for which insufficient information exists to determine that the controls referred to in clause (i) are sufficient to provide reasonable assurance of the safety and effectiveness of the device or to establish special controls to provide such assurance, but because it—"],[3,"(I) is not purported or represented to be for a use in supporting or sustaining human life or for a use which is of substantial importance in preventing impairment of human health, and"],[3,"(II) does not present a potential unreasonable risk of illness or injury,"],[2,"is to be regulated by the controls referred to in clause (i)."],[1,"(B) Class II, Special Controls.—A device which cannot be classified as a class I device because the general controls by themselves are insufficient to provide reasonable assurance of the safety and effectiveness of the device, and for which there is sufficient information to establish special controls to provide such assurance, including the promulgation of performance standards, postmarket surveillance, patient registries, development and dissemination of guidelines (including guidelines for the submission of clinical data in premarket notification submissions in accordance with section 360(k) of this title), recommendations, and other appropriate actions as the Secretary deems necessary to provide such assurance. For a device that is purported or represented to be for a use in supporting or sustaining human life, the Secretary shall examine and identify the special controls, if any, that are necessary to provide adequate assurance of safety and effectiveness and describe how such controls provide such assurance."],[1,"(C) Class III, Premarket Approval.—A device which because—"],[2,"(i) it (I) cannot be classified as a class I device because insufficient information exists to determine that the application of general controls are sufficient to provide reasonable assurance of the safety and effectiveness of the device, and (II) cannot be classified as a class II device because insufficient information exists to determine that the special controls described in subparagraph (B) would provide reasonable assurance of its safety and effectiveness, and"],[2,"(ii)(I) is purported or represented to be for a use in supporting or sustaining human life or for a use which is of substantial importance in preventing impairment of human health, or"],[2,"(II) presents a potential unreasonable risk of illness or injury,"],[1,"is to be subject, in accordance with section 360e of this title, to premarket approval to provide reasonable assurance of its safety and effectiveness."],[0,"If there is not sufficient information to establish a performance standard for a device to provide reasonable assurance of its safety and effectiveness, the Secretary may conduct such activities as may be necessary to develop or obtain such information."],[0,"(2) For purposes of this section and sections 360d and 360e of this title, the safety and effectiveness of a device are to be determined—"],[1,"(A) with respect to the persons for whose use the device is represented or intended,"],[1,"(B) with respect to the conditions of use prescribed, recommended, or suggested in the labeling of the device, and"],[1,"(C) weighing any probable benefit to health from the use of the device against any probable risk of injury or illness from such use."],[0,"(3)(A) Except as authorized by subparagraph (B), the effectiveness of a device is, for purposes of this section and sections 360d and 360e of this title, to be determined, in accordance with regulations promulgated by the Secretary, on the basis of well-controlled investigations, including 1 or more clinical investigations where appropriate, by experts qualified by training and experience to evaluate the effectiveness of the device, from which investigations it can fairly and responsibly be concluded by qualified experts that the device will have the effect it purports or is represented to have under the conditions of use prescribed, recommended, or suggested in the labeling of the device."],[0,"(B) If the Secretary determines that there exists valid scientific evidence (other than evidence derived from investigations described in subparagraph (A))—"],[1,"(i) which is sufficient to determine the effectiveness of a device, and"],[1,"(ii) from which it can fairly and responsibly be concluded by qualified experts that the device will have the effect it purports or is represented to have under the conditions of use prescribed, recommended, or suggested in the labeling of the device,"],[0,"then, for purposes of this section and sections 360d and 360e of this title, the Secretary may authorize the effectiveness of the device to be determined on the basis of such evidence."],[0,"(C) In making a determination of a reasonable assurance of the effectiveness of a device for which an application under section 360e of this title has been submitted, the Secretary shall consider whether the extent of data that otherwise would be required for approval of the application with respect to effectiveness can be reduced through reliance on postmarket controls."],[0,"(D)(i) The Secretary, upon the written request of any person intending to submit an application under section 360e of this title, shall meet with such person to determine the type of valid scientific evidence (within the meaning of subparagraphs (A) and (B)) that will be necessary to demonstrate for purposes of approval of an application the effectiveness of a device for the conditions of use proposed by such person. The written request shall include a detailed description of the device, a detailed description of the proposed conditions of use of the device, a proposed plan for determining whether there is a reasonable assurance of effectiveness, and, if available, information regarding the expected performance from the device. Within 30 days after such meeting, the Secretary shall specify in writing the type of valid scientific evidence that will provide a reasonable assurance that a device is effective under the conditions of use proposed by such person."],[0,"(ii) Any clinical data, including one or more well-controlled investigations, specified in writing by the Secretary for demonstrating a reasonable assurance of device effectiveness shall be specified as result of a determination by the Secretary that such data are necessary to establish device effectiveness. The Secretary shall consider, in consultation with the applicant, the least burdensome appropriate means of evaluating device effectiveness that would have a reasonable likelihood of resulting in approval."],[0,"(iii) For purposes of clause (ii), the term \"necessary\" means the minimum required information that would support a determination by the Secretary that an application provides reasonable assurance of the effectiveness of the device."],[0,"(iv) Nothing in this subparagraph shall alter the criteria for evaluating an application for premarket approval of a device."],[0,"(v) The determination of the Secretary with respect to the specification of valid scientific evidence under clauses (i) and (ii) shall be binding upon the Secretary, unless such determination by the Secretary could be contrary to the public health."],[0,"(b) Classification panels"],[0,"(1) For purposes of—"],[1,"(A) determining which devices intended for human use should be subject to the requirements of general controls, performance standards, or premarket approval, and"],[1,"(B) providing notice to the manufacturers and importers of such devices to enable them to prepare for the application of such requirements to devices manufactured or imported by them,"],[0,"the Secretary shall classify all such devices (other than devices classified by subsection (f)) into the classes established by subsection (a). For the purpose of securing recommendations with respect to the classification of devices, the Secretary shall establish panels of experts or use panels of experts established before May 28, 1976, or both. Section 1013 of title 5 shall not apply to the duration of a panel established under this paragraph."],[0,"(2) The Secretary shall appoint to each panel established under paragraph (1) persons who are qualified by training and experience to evaluate the safety and effectiveness of the devices to be referred to the panel and who, to the extent feasible, possess skill in the use of, or experience in the development, manufacture, or utilization of, such devices. The Secretary shall make appointments to each panel so that each panel shall consist of members with adequately diversified expertise in such fields as clinical and administrative medicine, engineering, biological and physical sciences, and other related professions. In addition, each panel shall include as nonvoting members a representative of consumer interests and a representative of interests of the device manufacturing industry. Scientific, trade, and consumer organizations shall be afforded an opportunity to nominate individuals for appointment to the panels. No individual who is in the regular full-time employ of the United States and engaged in the administration of this chapter may be a member of any panel. The Secretary shall designate one of the members of each panel to serve as chairman thereof."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/360c?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§360c. Classification of devices intended for human use","tname":"Food and Drugs","by":{"0":"1, 2, 2, 2, 2, 3, 11"}},{"t":"usc","label":"21 U.S.C. § 360e","url":"https://www.law.cornell.edu/uscode/text/21/360e","subs":["(a)","(b)(1)(A)","(b)(1)(B)","(c)(1)","(c)(2)","(d)","(d)(1)(A)","(d)(1)(B)","(d)(1)(B)(ii)","(d)(2)","(d)(2)(A)","(d)(2)(B)","(d)(2)(D)","(d)(3)(A)(ii)","(d)(6)","(d)(6)(A)(i)","(d)(6)(B)","(e)(1)"],"by":{"0":"2, 2, 2, 2, 9, 10, 11, 3, 9, 3, 3, 10, 3, 9, 3, 9, 3, 9, 10, 13, 3, 3, 4, 22"}},{"t":"usc","label":"21 U.S.C. § 360h","url":"https://www.law.cornell.edu/uscode/text/21/360h","subs":["(d)"],"stext":{"head":"§360h. Notification and other remedies","paras":[[0,"(a) Notification"],[0,"If the Secretary determines that—"],[1,"(1) a device intended for human use which is introduced or delivered for introduction into interstate commerce for commercial distribution presents an unreasonable risk of substantial harm to the public health, and"],[1,"(2) notification under this subsection is necessary to eliminate the unreasonable risk of such harm and no more practicable means is available under the provisions of this chapter (other than this section) to eliminate such risk,"],[0,"the Secretary may issue such order as may be necessary to assure that adequate notification is provided in an appropriate form, by the persons and means best suited under the circumstances involved, to all health professionals who prescribe or use the device and to any other person (including manufacturers, importers, distributors, retailers, and device users) who should properly receive such notification in order to eliminate such risk. An order under this subsection shall require that the individuals subject to the risk with respect to which the order is to be issued be included in the persons to be notified of the risk unless the Secretary determines that notice to such individuals would present a greater danger to the health of such individuals than no such notification. If the Secretary makes such a determination with respect to such individuals, the order shall require that the health professionals who prescribe or use the device provide for the notification of the individuals whom the health professionals treated with the device of the risk presented by the device and of any action which may be taken by or on behalf of such individuals to eliminate or reduce such risk. Before issuing an order under this subsection, the Secretary shall consult with the persons who are to give notice under the order."],[0,"(b) Repair, replacement, or refund"],[0,"(1)(A) If, after affording opportunity for an informal hearing, the Secretary determines that—"],[1,"(i) a device intended for human use which is introduced or delivered for introduction into interstate commerce for commercial distribution presents an unreasonable risk of substantial harm to the public health,"],[1,"(ii) there are reasonable grounds to believe that the device was not properly designed or manufactured with reference to the state of the art as it existed at the time of its design or manufacture,"],[1,"(iii) there are reasonable grounds to believe that the unreasonable risk was not caused by failure of a person other than a manufacturer, importer, distributor, or retailer of the device to exercise due care in the installation, maintenance, repair, or use of the device, and"],[1,"(iv) the notification authorized by subsection (a) would not by itself be sufficient to eliminate the unreasonable risk and action described in paragraph (2) of this subsection is necessary to eliminate such risk,"],[0,"the Secretary may order the manufacturer, importer, or any distributor of such device, or any combination of such persons, to submit to him within a reasonable time a plan for taking one or more of the actions described in paragraph (2). An order issued under the preceding sentence which is directed to more than one person shall specify which person may decide which action shall be taken under such plan and the person specified shall be the person who the Secretary determines bears the principal, ultimate financial responsibility for action taken under the plan unless the Secretary cannot determine who bears such responsibility or the Secretary determines that the protection of the public health requires that such decision be made by a person (including a device user or health professional) other than the person he determines bears such responsibility."],[0,"(B) The Secretary shall approve a plan submitted pursuant to an order issued under subparagraph (A) unless he determines (after affording opportunity for an informal hearing) that the action or actions to be taken under the plan or the manner in which such action or actions are to be taken under the plan will not assure that the unreasonable risk with respect to which such order was issued will be eliminated. If the Secretary disapproves a plan, he shall order a revised plan to be submitted to him within a reasonable time. If the Secretary determines (after affording opportunity for an informal hearing) that the revised plan is unsatisfactory or if no revised plan or no initial plan has been submitted to the Secretary within the prescribed time, the Secretary shall (i) prescribe a plan to be carried out by the person or persons to whom the order issued under subparagraph (A) was directed, or (ii) after affording an opportunity for an informal hearing, by order prescribe a plan to be carried out by a person who is a manufacturer, importer, distributor, or retailer of the device with respect to which the order was issued but to whom the order under subparagraph (A) was not directed."],[0,"(2) The actions which may be taken under a plan submitted under an order issued under paragraph (1) are as follows:"],[1,"(A) To repair the device so that it does not present the unreasonable risk of substantial harm with respect to which the order under paragraph (1) was issued."],[1,"(B) To replace the device with a like or equivalent device which is in conformity with all applicable requirements of this chapter."],[1,"(C) To refund the purchase price of the device (less a reasonable allowance for use if such device has been in the possession of the device user for one year or more—"],[2,"(i) at the time of notification ordered under subsection (a), or"],[2,"(ii) at the time the device user receives actual notice of the unreasonable risk with respect to which the order was issued under paragraph (1),"],[1,"whichever first occurs)."],[0,"(3) No charge shall be made to any person (other than a manufacturer, importer, distributor or retailer) for availing himself of any remedy, described in paragraph (2) and provided under an order issued under paragraph (1), and the person subject to the order shall reimburse each person (other than a manufacturer, importer, distributor, or retailer) who is entitled to such a remedy for any reasonable and foreseeable expenses actually incurred by such person in availing himself of such remedy."],[0,"(c) Reimbursement"],[0,"An order issued under subsection (b) with respect to a device may require any person who is a manufacturer, importer, distributor, or retailer of the device to reimburse any other person who is a manufacturer, importer, distributor, or retailer of such device for such other person's expenses actually incurred in connection with carrying out the order if the Secretary determines such reimbursement is required for the protection of the public health. Any such requirement shall not affect any rights or obligations under any contract to which the person receiving reimbursement or the person making such reimbursement is a party."],[0,"(d) Effect on other liability"],[0,"Compliance with an order issued under this section shall not relieve any person from liability under Federal or State law. In awarding damages for economic loss in an action brought for the enforcement of any such liability, the value to the plaintiff in such action of any remedy provided him under such order shall be taken into account."],[0,"(e) Recall authority"],[0,"(1) If the Secretary finds that there is a reasonable probability that a device intended for human use would cause serious, adverse health consequences or death, the Secretary shall issue an order requiring the appropriate person (including the manufacturers, importers, distributors, or retailers of the device)—"],[1,"(A) to immediately cease distribution of such device, and"],[1,"(B) to immediately notify health professionals and device user facilities of the order and to instruct such professionals and facilities to cease use of such device."],[0,"The order shall provide the person subject to the order with an opportunity for an informal hearing, to be held not later than 10 days after the date of the issuance of the order, on the actions required by the order and on whether the order should be amended to require a recall of such device. If, after providing an opportunity for such a hearing, the Secretary determines that inadequate grounds exist to support the actions required by the order, the Secretary shall vacate the order."],[0,"(2)(A) If, after providing an opportunity for an informal hearing under paragraph (1), the Secretary determines that the order should be amended to include a recall of the device with respect to which the order was issued, the Secretary shall, except as provided in subparagraphs (B) and (C), amend the order to require a recall. The Secretary shall specify a timetable in which the device recall will occur and shall require periodic reports to the Secretary describing the progress of the recall."],[0,"(B) An amended order under subparagraph (A)—"],[1,"(i) shall—"],[2,"(I) not include recall of a device from individuals, and"],[2,"(II) not include recall of a device from device user facilities if the Secretary determines that the risk of recalling such device from the facilities presents a greater health risk than the health risk of not recalling the device from use, and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/360h?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§360h. Notification and other remedies","tname":"Food and Drugs","by":{"0":"18"}},{"t":"usc","label":"21 U.S.C. § 360i","url":"https://www.law.cornell.edu/uscode/text/21/360i","subs":["(a)"],"stext":{"head":"§360i. Records and reports on devices","paras":[[0,"(a) General rule"],[0,"Every person who is a manufacturer or importer of a device intended for human use shall establish and maintain such records, make such reports, and provide such information, as the Secretary may by regulation reasonably require to assure that such device is not adulterated or misbranded and to otherwise assure its safety and effectiveness. Regulations prescribed under the preceding sentence—"],[1,"(1) shall require a device manufacturer or importer to report to the Secretary whenever the manufacturer or importer receives or otherwise becomes aware of information that reasonably suggests that one of its marketed devices—"],[2,"(A) may have caused or contributed to a death or serious injury, or"],[2,"(B) has malfunctioned and that such device or a similar device marketed by the manufacturer or importer would be likely to cause or contribute to a death or serious injury if the malfunction were to recur, which report under this subparagraph—"],[3,"(i) shall be submitted in accordance with part 803 of title 21, Code of Federal Regulations (or successor regulations), unless the Secretary grants an exemption or variance from, or an alternative to, a requirement under such regulations pursuant to section 803.19 of such part, if the device involved is—"],[4,"(I) a class III device;"],[4,"(II) a class II device that is permanently implantable, is life supporting, or is life sustaining; or"],[4,"(III) a type of device which the Secretary has, by notice published in the Federal Register or letter to the person who is the manufacturer or importer of the device, indicated should be subject to such part 803 in order to protect the public health;"],[3,"(ii) shall, if the device is not subject to clause (i), be submitted in accordance with criteria established by the Secretary for reports made pursuant to this clause, which criteria shall require the reports to be in summary form and made on a quarterly basis; or"],[3,"(iii) shall, if the device is imported into the United States and for which part 803 of title 21, Code of Federal Regulations (or successor regulations) requires an importer to submit a report to the manufacturer, be submitted by the importer to the manufacturer in accordance with part 803 of title 21, Code of Federal Regulations (or successor regulations) 1"],[1,"(2) shall define the term \"serious injury\" to mean an injury that—"],[2,"(A) is life threatening,"],[2,"(B) results in permanent impairment of a body function or permanent damage to a body structure, or"],[2,"(C) necessitates medical or surgical intervention to preclude permanent impairment of a body function or permanent damage to a body structure;"],[1,"(3) shall require reporting of other significant adverse device experiences as determined by the Secretary to be necessary to be reported;"],[1,"(4) shall not impose requirements unduly burdensome to a device manufacturer or importer taking into account his cost of complying with such requirements and the need for the protection of the public health and the implementation of this chapter;"],[1,"(5) which prescribe the procedure for making requests for reports or information shall require that each request made under such regulations for submission of a report or information to the Secretary state the reason or purpose for such request and identify to the fullest extent practicable such report or information;"],[1,"(6) which require submission of a report or information to the Secretary shall state the reason or purpose for the submission of such report or information and identify to the fullest extent practicable such report or information;"],[1,"(7) may not require that the identity of any patient be disclosed in records, reports, or information required under this subsection unless required for the medical welfare of an individual, to determine the safety or effectiveness of a device, or to verify a record, report, or information submitted under this chapter; and"],[1,"(8) may not require a manufacturer or importer of a class I device to—"],[2,"(A) maintain for such a device records respecting information not in the possession of the manufacturer or importer, or"],[2,"(B) to submit for such a device to the Secretary any report or information—"],[3,"(i) not in the possession of the manufacturer or importer, or"],[3,"(ii) on a periodic basis,"],[1,"unless such report or information is necessary to determine if the device should be reclassified or if the device is adulterated or misbranded. and 2"],[0,"In prescribing such regulations, the Secretary shall have due regard for the professional ethics of the medical profession and the interests of patients. The prohibitions of paragraph (7) of this subsection continue to apply to records, reports, and information concerning any individual who has been a patient, irrespective of whether or when he ceases to be a patient. The Secretary shall by regulation require distributors to keep records and make such records available to the Secretary upon request. Paragraphs (4) and (8) apply to distributors to the same extent and in the same manner as such paragraphs apply to manufacturers and importers."],[0,"(b) User reports"],[0,"(1)(A) Whenever a device user facility receives or otherwise becomes aware of information that reasonably suggests that a device has or may have caused or contributed to the death of a patient of the facility, the facility shall, as soon as practicable but not later than 10 working days after becoming aware of the information, report the information to the Secretary and, if the identity of the manufacturer is known, to the manufacturer of the device. In the case of deaths, the Secretary may by regulation prescribe a shorter period for the reporting of such information."],[0,"(B) Whenever a device user facility receives or otherwise becomes aware of—"],[1,"(i) information that reasonably suggests that a device has or may have caused or contributed to the serious illness of, or serious injury to, a patient of the facility, or"],[1,"(ii) other significant adverse device experiences as determined by the Secretary by regulation to be necessary to be reported,"],[0,"the facility shall, as soon as practicable but not later than 10 working days after becoming aware of the information, report the information to the manufacturer of the device or to the Secretary if the identity of the manufacturer is not known."],[0,"(C) Each device user facility shall submit to the Secretary on an annual basis a summary of the reports made under subparagraphs (A) and (B). Such summary shall be submitted on January 1 of each year. The summary shall be in such form and contain such information from such reports as the Secretary may require and shall include—"],[1,"(i) sufficient information to identify the facility which made the reports for which the summary is submitted,"],[1,"(ii) in the case of any product which was the subject of a report, the product name, serial number, and model number,"],[1,"(iii) the name and the address of the manufacturer of such device, and"],[1,"(iv) a brief description of the event reported to the manufacturer."],[0,"(D) For purposes of subparagraphs (A), (B), and (C), a device user facility shall be treated as having received or otherwise become aware of information with respect to a device of that facility when medical personnel who are employed by or otherwise formally affiliated with the facility receive or otherwise become aware of information with respect to that device in the course of their duties."],[0,"(2) The Secretary may not disclose the identity of a device user facility which makes a report under paragraph (1) except in connection with—"],[1,"(A) an action brought to enforce section 331(q) of this title, or"],[1,"(B) a communication to a manufacturer of a device which is the subject of a report under paragraph (1)."],[0,"This paragraph does not prohibit the Secretary from disclosing the identity of a device user facility making a report under paragraph (1) or any information in such a report to employees of the Department of Health and Human Services, to the Department of Justice, or to the duly authorized committees and subcommittees of the Congress."],[0,"(3) No report made under paragraph (1) by—"],[1,"(A) a device user facility,"],[1,"(B) an individual who is employed by or otherwise formally affiliated with such a facility, or"],[1,"(C) a physician who is not required to make such a report,"],[0,"shall be admissible into evidence or otherwise used in any civil action involving private parties unless the facility, individual, or physician who made the report had knowledge of the falsity of the information contained in the report."],[0,"(4) A report made under paragraph (1) does not affect any obligation of a manufacturer who receives the report to file a report as required under subsection (a)."],[0,"(5) With respect to device user facilities:"],[1,"(A) The Secretary shall by regulation plan and implement a program under which the Secretary limits user reporting under paragraphs (1) through (4) to a subset of user facilities that constitutes a representative profile of user reports for device deaths and serious illnesses or serious injuries."],[1,"(B) During the period of planning the program under subparagraph (A), paragraphs (1) through (4) continue to apply."],[1,"(C) During the period in which the Secretary is providing for a transition to the full implementation of the program, paragraphs (1) through (4) apply except to the extent that the Secretary determines otherwise."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/360i?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§360i. Records and reports on devices","tname":"Food and Drugs","by":{"0":"3"}},{"t":"usc","label":"21 U.S.C. § 360j","url":"https://www.law.cornell.edu/uscode/text/21/360j","subs":["(e)(1)"],"by":{"0":"3"}},{"t":"usc","label":"21 U.S.C. § 360k","url":"https://www.law.cornell.edu/uscode/text/21/360k","subs":["(a)","(b)","(b)(1)"],"stext":{"head":"§360k. State and local requirements respecting devices","paras":[[0,"(a) General rule"],[0,"Except as provided in subsection (b), no State or political subdivision of a State may establish or continue in effect with respect to a device intended for human use any requirement—"],[1,"(1) which is different from, or in addition to, any requirement applicable under this chapter to the device, and"],[1,"(2) which relates to the safety or effectiveness of the device or to any other matter included in a requirement applicable to the device under this chapter."],[0,"(b) Exempt requirements"],[0,"Upon application of a State or a political subdivision thereof, the Secretary may, by regulation promulgated after notice and opportunity for an oral hearing, exempt from subsection (a), under such conditions as may be prescribed in such regulation, a requirement of such State or political subdivision applicable to a device intended for human use if—"],[1,"(1) the requirement is more stringent than a requirement under this chapter which would be applicable to the device if an exemption were not in effect under this subsection; or"],[1,"(2) the requirement—"],[2,"(A) is required by compelling local conditions, and"],[2,"(B) compliance with the requirement would not cause the device to be in violation of any applicable requirement under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/360k?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§360k. State and local requirements respecting devices","tname":"Food and Drugs","by":{"0":"passim, 4, 5, 7, 8, 19, 26, 4, 17, 18"}},{"t":"usc","label":"21 U.S.C. § 360","url":"https://www.law.cornell.edu/uscode/text/21/360","subs":["(k)"],"stext":{"head":"§360. Registration of producers of drugs or devices","paras":[[0,"(a) Definitions"],[0,"As used in this section—"],[1,"(1) the term \"manufacture, preparation, propagation, compounding, or processing\" shall include repackaging or otherwise changing the container, wrapper, or labeling of any drug package or device package in furtherance of the distribution of the drug or device from the original place of manufacture to the person who makes final delivery or sale to the ultimate consumer or user; and"],[1,"(2) the term \"name\" shall include in the case of a partnership the name of each partner and, in the case of a corporation, the name of each corporate officer and director, and the State of incorporation."],[0,"(b) Annual registration"],[0,"(1) During the period beginning on October 1 and ending on December 31 of each year, every person who owns or operates any establishment in any State engaged in the manufacture, preparation, propagation, compounding, or processing of a drug or drugs shall register with the Secretary the name of such person, places of business of such person, all such establishments, the unique facility identifier of each such establishment, and a point of contact e-mail address."],[0,"(2) During the period beginning on October 1 and ending on December 31 of each year, every person who owns or operates any establishment in any State engaged in the manufacture, preparation, propagation, compounding, or processing of a device or devices shall register with the Secretary his name, places of business, and all such establishments."],[0,"(3) The Secretary shall specify the unique facility identifier system that shall be used by registrants under paragraph (1). The requirement to include a unique facility identifier in a registration under paragraph (1) shall not apply until the date that the identifier system is specified by the Secretary under the preceding sentence."],[0,"(c) New producers"],[0,"Every person upon first engaging in the manufacture, preparation, propagation, compounding, or processing of a drug or drugs or a device or devices in any establishment which he owns or operates in any State shall immediately register with the Secretary—"],[1,"(1) with respect to drugs, the information described under subsection (b)(1); and"],[1,"(2) with respect to devices, the information described under subsection (b)(2)..1"],[0,"(d) Additional establishments"],[0,"Every person duly registered in accordance with the foregoing subsections of this section shall immediately register with the Secretary any additional establishment which he owns or operates in any State and in which he begins the manufacture, preparation, propagation, compounding, or processing of a drug or drugs or a device or devices."],[0,"(e) Registration number; uniform system for identification of devices intended for human use"],[0,"The Secretary may assign a registration number to any person or any establishment registered in accordance with this section. The Secretary may also assign a listing number to each drug or class of drugs listed under subsection (j). Any number assigned pursuant to the preceding sentence shall be the same as that assigned pursuant to the National Drug Code. The Secretary may by regulation prescribe a uniform system for the identification of devices intended for human use and may require that persons who are required to list such devices pursuant to subsection (j) shall list such devices in accordance with such system."],[0,"(f) Availability of registrations for inspection"],[0,"The Secretary shall make available for inspection, to any person so requesting, any registration filed pursuant to this section; except that any list submitted pursuant to paragraph (3) of subsection (j) and the information accompanying any list or notice filed under paragraph (1) or (2) of that subsection shall be exempt from such inspection unless the Secretary finds that such an exemption would be inconsistent with protection of the public health."],[0,"(g) Exclusions from application of section"],[0,"The foregoing subsections of this section shall not apply to—"],[1,"(1) pharmacies which maintain establishments in conformance with any applicable local laws regulating the practice of pharmacy and medicine and which are regularly engaged in dispensing prescription drugs or devices, upon prescriptions of practitioners licensed to administer such drugs or devices to patients under the care of such practitioners in the course of their professional practice, and which do not manufacture, prepare, propagate, compound, or process drugs or devices for sale other than in the regular course of their business of dispensing or selling drugs or devices at retail;"],[1,"(2) practitioners licensed by law to prescribe or administer drugs or devices and who manufacture, prepare, propagate, compound, or process drugs or devices solely for use in the course of their professional practice;"],[1,"(3) persons who manufacture, prepare, propagate, compound, or process drugs or devices solely for use in research, teaching, or chemical analysis and not for sale;"],[1,"(4) any distributor who acts as a wholesale distributor of devices, and who does not manufacture, repackage, process, or relabel a device; or"],[1,"(5) such other classes of persons as the Secretary may by regulation exempt from the application of this section upon a finding that registration by such classes of persons in accordance with this section is not necessary for the protection of the public health."],[0,"In this subsection, the term \"wholesale distributor\" means any person (other than the manufacturer or the initial importer) who distributes a device from the original place of manufacture to the person who makes the final delivery or sale of the device to the ultimate consumer or user."],[0,"(h) Inspections"],[0,"(1) In general"],[1,"Every establishment that is required to be registered with the Secretary under this section shall be subject to inspection pursuant to section 374 of this title."],[0,"(2) Risk-based schedule for devices"],[0,"(A) In general"],[2,"The Secretary, acting through one or more officers or employees duly designated by the Secretary, shall inspect establishments described in paragraph (1) that are engaged in the manufacture, propagation, compounding, or processing of a device or devices (referred to in this subsection as \"device establishments\") in accordance with a risk-based schedule established by the Secretary."],[0,"(B) Factors and considerations"],[2,"In establishing the risk-based schedule under subparagraph (A), the Secretary shall—"],[3,"(i) apply, to the extent applicable for device establishments, the factors identified in paragraph (4); and"],[3,"(ii) consider the participation of the device establishment, as applicable, in international device audit programs in which the United States participates or the United States recognizes for purposes of inspecting device establishments."],[0,"(3) Risk-based schedule for drugs"],[1,"The Secretary, acting through one or more officers or employees duly designated by the Secretary, shall inspect establishments described in paragraph (1) that are engaged in the manufacture, preparation, propagation, compounding, or processing of a drug or drugs (referred to in this subsection as \"drug establishments\") in accordance with a risk-based schedule established by the Secretary."],[0,"(4) Risk factors"],[1,"In establishing a risk-based schedule under paragraph (2) or (3), the Secretary shall inspect establishments according to the known safety risks of such establishments, which shall be based on the following factors:"],[2,"(A) The compliance history of the establishment."],[2,"(B) The record, history, and nature of recalls linked to the establishment."],[2,"(C) The inherent risk of the drug or device manufactured, prepared, propagated, compounded, or processed at the establishment."],[2,"(D) The inspection frequency and history of the establishment, including whether the establishment has been inspected pursuant to section 374 of this title within the last 4 years."],[2,"(E) Whether the establishment has been inspected by a foreign government or an agency of a foreign government recognized under section 384e of this title."],[2,"(F) The compliance history of establishments in the country or region in which the establishment is located that are subject to regulation under this chapter, including the history of violations related to products exported from such country or region that are subject to such regulation."],[2,"(G) Any other criteria deemed necessary and appropriate by the Secretary for purposes of allocating inspection resources."],[0,"(5) Effect of status"],[1,"In determining the risk associated with an establishment for purposes of establishing a risk-based schedule under paragraph (3), the Secretary shall not consider whether the drugs manufactured, prepared, propagated, compounded, or processed by such establishment are drugs described in section 353(b) of this title."],[0,"(6) Annual report on inspections of establishments"],[1,"Not later than May 1 of each year, the Secretary shall make available on the Internet Web site of the Food and Drug Administration a report regarding—"],[2,"(A)(i) the number of domestic and foreign establishments registered pursuant to this section in the previous fiscal year;"],[2,"(ii) the number of such registered establishments in each region of interest;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/360?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§360. Registration of producers of drugs or devices","tname":"Food and Drugs","by":{"0":"2, 8"}},{"t":"reg","label":"42 Fed. Reg. 30,384","url":"https://www.govinfo.gov/link/fr/42/30384","by":{"0":"27"}},{"t":"reg","label":"44 Fed. Reg. 37,447","url":"https://www.govinfo.gov/link/fr/44/37447","by":{"0":"13"}},{"t":"reg","label":"61 Fed. Reg. 44,413","url":"https://www.govinfo.gov/link/fr/61/44413","by":{"0":"11, 19"}},{"t":"reg","label":"65 Fed. Reg. 81,083","url":"https://www.govinfo.gov/link/fr/65/81083","by":{"0":"11"}},{"t":"reg","label":"71 Fed. Reg. 3935","url":"https://www.govinfo.gov/link/fr/71/3935","by":{"0":"13, 22"}}]};